import React, { useState } from 'react';
import Login from './components/Login';
import Signup from './components/signup';
import Navbar from './components/Navbar';
import DocumentList from './components/DocumentList';
import DocumentForm from './components/DocumentForm';
import DocumentDetail from './components/DocumentDetail';
import SignatureHistory from './components/SignatureHistory';

function App() {
    const [user, setUser] = useState(null);
    const [page, setPage] = useState('liste');
    const [documentId, setDocumentId] = useState(null);
    const [afficherInscription, setAfficherInscription] = useState(false);

    const handleLogin = (utilisateurConnecte) => {
        setUser(utilisateurConnecte);
        setPage('liste');
    };

    const handleDeconnexion = () => {
        setUser(null);
    };

    const handleVoirDocument = (id) => {
        setDocumentId(id);
        setPage('detail');
    };

    if (!user) {
        if (afficherInscription) {
            return (
                <Signup
                    onInscrit={(email) => setAfficherInscription(false)}
                    onAllerConnexion={() => setAfficherInscription(false)}
                />
            );
        }
        return (
            <Login
                onLogin={handleLogin}
                onAllerInscription={() => setAfficherInscription(true)}
            />
        );
    }

    return (
        <div>
            <Navbar user={user} onNaviguer={setPage} onDeconnexion={handleDeconnexion} />

            {page === 'liste' && <DocumentList onVoirDocument={handleVoirDocument} />}

            {page === 'creer' && (
                <DocumentForm user={user} onDocumentCree={() => setPage('liste')} />
            )}

            {page === 'detail' && (
                <DocumentDetail
                    documentId={documentId}
                    user={user}
                    onRetour={() => setPage('liste')}
                />
            )}

            {page === 'historique' && <SignatureHistory />}
        </div>
    );
}

export default App;
